// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(address depositor, uint256 amount, address querier) public {
        vm.assume(depositor != address(0));
        vm.assume(querier != address(0));
        vm.assume(depositor != querier);
        amount = bound(amount, 1, 1e30);

        vm.deal(depositor, amount);
        vm.prank(depositor);
        c.addToBalance{value: amount}();

        vm.prank(querier);
        uint256 balanceQueried = c.getBalance(depositor);

        assertEq(balanceQueried, amount);
    }
}
